// Internal H5-011 verification derived from SPEC-FR-COORD-008 and expected C01.
import {before,after,test} from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {isolatedBoundaries,read,write} from '../support/h5-boundary-isolated.ts';
import {holdFixture} from '../support/h4-hold-fixtures.ts';
import {H5011ProjectionAdapter} from '../../src/infrastructure/postgres/h5-projection-adapter.ts';
let h:Awaited<ReturnType<typeof isolatedBoundaries>>,reader:H5011ProjectionAdapter;
before(async()=>{h=await isolatedBoundaries('crm_h5011_c01_preservation',59233);await h.migration.unsafe(await readFile('supabase/migrations/20261014003559_h5_authorized_projections.sql','utf8'));reader=new H5011ProjectionAdapter(h.runtime,h.f1,h.f2);});
after(async()=>{await h?.close();});
test('H5-011 INTERNAL C01 known canonical hold deadline must be derivable from scoped calendar output',async()=>{
 const expiresAt='2026-11-19T10:15:00Z',f=await holdFixture(h,expiresAt);await f.apply(await f.grant());const q=await f.prepareConversion();await h.booking.apply(await h.auth(),write,q);
 const original=await f.state();assert.ok(original);assert.equal(Date.parse(original.parts[0]!.terms.expiresAt!),Date.parse(expiresAt));
 const projection=await reader.read(await h.auth(),read,{contextKind:'booking',contextId:q.bookingId,surface:'calendar',destination:'administrator'});assert.ok(projection);assert.equal(projection.mutationAuthority,false);
 const hold=projection.entries.find((e:any)=>e.source==='crm_private.b04_holds'&&e.data.hold_id===f.holdId);assert.ok(hold,'canonical hold reference must be in this Booking');
 const strings=(value:unknown):string[]=>typeof value==='string'?[value]:Array.isArray(value)?value.flatMap(strings):value&&typeof value==='object'?Object.values(value).flatMap(strings):[];
 const projected=hold as {data:{hold_id:string;opportunity_id:string}};
 const followed=await h.holds.read(await h.auth(),read,projected.data.hold_id,projected.data.opportunity_id);assert.ok(followed);
 const direct=strings(projection).filter(value=>Number.isFinite(Date.parse(value))&&Date.parse(value)===Date.parse(expiresAt));
 const found=strings(followed).filter(value=>Number.isFinite(Date.parse(value))&&Date.parse(value)===Date.parse(expiresAt));
 assert.deepEqual(await f.state(),original,'projection does not mutate canonical hold state');
 console.log('H5011-C01-CANONICAL-DEADLINE',JSON.stringify({holdId:f.holdId,bookingId:q.bookingId,expectedDeadline:expiresAt,canonicalParts:original.parts,projection,directDeadlineValues:direct,followedCanonicalHold:followed,matchedCanonicalDeadlineValues:found}));
 assert.ok(found.length>0,'SPEC-FR-COORD-008 / expected C01: known canonical hold deadline must be recoverable by following the scoped reference, with no field/format imposed');
});

// Additional implementation verification, H5-011 only. Runs in a disposable copy.
import {before,after,test} from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {randomUUID as uid,createHash} from 'node:crypto';
import {isolatedBoundaries,read,write} from '../support/h5-boundary-isolated.ts';
import {bookingFixture} from '../support/h2-booking-fixtures.ts';
import {obligationFixture} from '../support/h3-obligation-fixtures.ts';
import {holdFixture} from '../support/h4-hold-fixtures.ts';
import {invoiceFixture} from '../support/h3-invoice-fixtures.ts';
import {requirementFixture} from '../support/h4-requirement-fixtures.ts';
import {modificationFixture} from '../support/h4-modification-fixtures.ts';
import {H5011ProjectionAdapter} from '../../src/infrastructure/postgres/h5-projection-adapter.ts';
import {H5001TaskAdapter} from '../../src/infrastructure/postgres/h5-task-adapter.ts';
import {H1003ResolutionAdapter} from '../../src/infrastructure/postgres/h1-resolution-adapter.ts';
import {projectCivilReference} from '../../src/domain/coordinated-projection.ts';
import {civilReference,localDate,zoneEvidence} from '../../src/domain/civil-time.ts';
import {evaluateTaskDeadline} from '../../src/domain/pending-task.ts';
import {evaluateDerivedExpected} from '../../src/domain/payment-obligation.ts';
let h:any,reader:H5011ProjectionAdapter,tasks:H5001TaskAdapter;
before(async()=>{h=await isolatedBoundaries('crm_h5011_internal_completion',59231);await h.migration.unsafe(await readFile('supabase/migrations/20261014003559_h5_authorized_projections.sql','utf8'));reader=new H5011ProjectionAdapter(h.runtime,h.f1,h.f2);tasks=new H5001TaskAdapter(h.runtime,h.f1,h.f2);});
after(async()=>{await h?.close();});
const q=(id:string,extra:Record<string,unknown>={})=>({contextKind:'booking' as const,contextId:id,surface:'timeline' as const,destination:'administrator' as const,...extra});
const rows=(r:any,table:string)=>r.entries.filter((e:any)=>e.source==='crm_private.'+table).map((e:any)=>e.data);
const view=async(id:string,extra:Record<string,unknown>={})=>reader.read(await h.auth(),read,q(id,extra));
const zone=zoneEvidence('Europe/Madrid','SYNTHETIC retained contractual zone','1');
const hash=async(value:unknown)=>String((await h.observer`select encode(crm_crypto.digest(convert_to(${JSON.stringify(value)}::text::jsonb::text,'UTF8'),'sha256'),'hex') hash`)[0].hash);
async function makeTask(bookingId:string,deadline:any,scopeRef=bookingId,causeKind='final_participants'){
 const command={action:'receive' as const,operationId:uid(),taskId:uid(),expectedRevision:0,identity:{causeKind,causeId:uid(),contextKind:'booking',contextId:bookingId,scopeRef,relatedKind:null,relatedId:null,effect:causeKind==='document'?'document-review':'final-participants-review'},material:{title:'SYNTHETIC configured pending internal work',deadline,priority:{kind:'pending' as const,reason:'SYNTHETIC priority not configured'},sourceRef:'SYNTHETIC explicit local setup',sourceVersion:'1',triggerRef:'BR-TASK-005' as const,triggerVersion:'1'},reason:'SYNTHETIC authorized known scope and deadline'};
 await tasks.apply(await h.auth(),write,command);return command;
}
async function businessSnapshot(bookingId:string){
 const names=['b04_bookings','b04_services','b04_modalities','b04_contributions','b04_history','b05_payment_schedules','b05_schedule_revisions','b05_expected_payments','b05_allocations','b07_pending_tasks'];const data=[];
 for(const table of names){const result=await h.observer.unsafe(`select to_jsonb(x) value from crm_private.${table} x order by to_jsonb(x)::text`);data.push({table,rows:Array.from(result)});}
 return createHash('sha256').update(JSON.stringify({bookingId,data})).digest('hex');
}
async function publishSchedule(booking:any,at:string){
 const bid=booking.bookingId,policyId=uid(),scheduleId=uid();
 const attest=async(command:any)=>{const claim='obligation:'+command.action+':'+await hash(Object.fromEntries(Object.entries(command).filter(([k,v])=>!['operationId','evidenceId','computed'].includes(k)&&v!==undefined)));const proof=h.req('evidence',{claim,coverage:booking.coverage,certainty:'reviewed',source_kind:'manual'},booking.opportunityId);await h.evidence.apply(await h.auth(),write,{...proof,coverage:booking.coverage,occurredAt:command.at});return {...command,evidenceId:proof.targetId};};
 const base={operationId:uid(),bookingId:bid,policyId,expectedRevision:0,sourceRef:'SYNTHETIC approved ordinary policy',reason:'SYNTHETIC explicit policy setup',at,evidenceId:uid()};await h.obligations.apply(await h.auth(),write,await attest({...base,action:'publish_policy',policyVersion:1,selectors:{}}));
 const amount=String((await h.observer`select sum(m.final_person_price*m.participants)::text amount from crm_private.b04_modalities bm join crm_private.b03_proposal_modalities m on m.version_id=${booking.versionId}::uuid and m.modality_id=bm.modality_id where bm.booking_id=${bid}::uuid`)[0].amount);
 const date=String((await h.observer`select min(l.service_date)::text date from crm_private.b04_contributions c join crm_private.b03_proposal_lines l on l.version_id=${booking.versionId}::uuid and l.line_id=c.line_id where c.booking_id=${bid}::uuid`)[0].date);
 const command={...base,action:'determine',operationId:uid(),scheduleId,scope:'global',scopeId:bid,policy:{id:policyId,version:1,rule:'ordinary_50_50'},definition:{base:{amount,sourceRef:booking.versionId,version:'1'},reference:civilReference({scope:'global',scopeId:bid},localDate(date),zone,booking.versionId,'1'),at}};
 await h.obligations.apply(await h.auth(),write,await attest(command));return scheduleId;
}
async function mixedBooking(){
 const seed=await bookingFixture(h,'total',false),f=seed.f,content=structuredClone(f.content);content.scope='SYNTHETIC 20/22/23 November accepted scope';
 for(const [i,m] of content.modalities.entries()){m.lines[0]!.date=i?'2026-11-22':'2026-11-20';}
 content.modalities[1]!.lines.push({...content.modalities[1]!.lines[0]!,id:uid(),date:'2026-11-23'});
 const proposalId=uid(),versionId=uid(),opportunityId=f.opp.targetId;
 const rev=async()=>({expectedRevision:Number((await h.observer`select revision from crm_private.b03_proposals where proposal_id=${proposalId}::uuid`)[0]?.revision??0),expectedOpportunityRevision:Number((await h.observer`select revision from crm_private.b03_opportunities where opportunity_id=${opportunityId}::uuid`)[0].revision)});
 const prepare={action:'prepare' as const,operationId:uid(),proposalId,opportunityId,...await rev(),sourceRef:'SYNTHETIC new accepted multiday fixture',reason:'SYNTHETIC controlled calendar coverage',content};await h.proposal.apply(await h.auth(),write,prepare);await h.proposal.apply(await h.auth(),write,{...prepare,action:'fix',operationId:uid(),versionId,content:undefined,...await rev()});
 const at=new Date().toISOString(),proof=(claim:string)=>f.proof(claim,content.scope,at);
 await h.offer.apply(await h.auth(),write,{action:'issue',operationId:uid(),proposalId,opportunityId,versionId,...await rev(),coverage:content.scope,at,issuance:{issuedAt:at,limits:[]},sourceRef:'SYNTHETIC',reason:'SYNTHETIC',evidenceId:await proof(`offer:issue:${versionId}:${at}:7`)});
 const acceptanceId=uid();await h.acceptance.apply(await h.auth(),write,{action:'register',operationId:uid(),acceptanceId,proposalId,opportunityId,versionId,...await rev(),coverage:content.scope,at,accepterId:f.accepterId,designationId:f.designationId,channel:'phone',terms:content.terms,authorityEvidenceId:await proof(`acceptance:authority:${versionId}:${f.accepterId}:${f.designationId}`),evidenceId:await proof(`acceptance:agree:${versionId}:${acceptanceId}:${f.accepterId}:phone`),sourceRef:'SYNTHETIC',reason:'SYNTHETIC'});
 const reviewEvidence:any={};for(const aspect of ['prices','availability','conditions','capacity'])reviewEvidence[aspect]=await proof(`offer:review:${versionId}:${acceptanceId}:accept:${aspect}`);
 await h.acceptance.apply(await h.auth(),write,{action:'verify',operationId:uid(),acceptanceId,proposalId,opportunityId,versionId,...await rev(),coverage:content.scope,at,reviewEvidence,won:true,sourceRef:'SYNTHETIC',reason:'SYNTHETIC'});
 const detail={services:content.modalities.flatMap((m:any)=>m.lines.map((l:any)=>{const id=uid(),contributionId=uid();return{id,serviceRevisionId:l.serviceRevisionId,nature:'external',variant:null,provider:null,place:null,schedule:null,contributions:[{id:contributionId,lineId:l.id,modalityId:m.id,quantity:l.quantity,attendees:m.participants,certainty:'estimated'}],nights:l.date==='2026-11-23'?[{id:uid(),date:l.date,contributionIds:[contributionId]}]:[]};})),participants:[],assignments:[]};
 const command={operationId:uid(),bookingId:uid(),opportunityId,proposalId,versionId,acceptanceId,coverage:content.scope,terms:content.terms,...await rev(),sourceRef:'SYNTHETIC',reason:'SYNTHETIC multiday booking',evidenceId:await proof(`booking:detail:${acceptanceId}:${await hash(detail)}`),detail,route:'normal'};await h.booking.apply(await h.auth(),write,command);return {command,content,detail};
}
test('H5-011 INTERNAL C03 integrated November13 full day and14 balance/final-count projection, no economic writes',async()=>{
 const f=await obligationFixture(h,'1000.00','2026-11-12T10:00:00Z',['2026-11-20','2026-11-22']);await h.obligations.apply(await h.auth(),write,f.q);
 const reference=f.q.definition!.reference,task=await makeTask(f.b.bookingId,{kind:'d020',reference,daysBefore:7,sourceRef:'SYNTHETIC accredited seven-day final-count setting',version:'1'});
 const before=await businessSnapshot(f.b.bookingId),projection=await view(f.b.bookingId),snapshot=rows(projection,'b05_schedule_revisions').find((x:any)=>x.schedule_id===f.q.scheduleId).snapshot;
 const expected=rows(await view(f.b.bookingId,{surface:'calendar'}),'b05_expected_payments').find((x:any)=>x.slot==='balance');assert.equal(String(expected.amount),'500');assert.deepEqual(expected.due,{kind:'civil',date:'2026-11-13'});
 const pending=rows(projection,'b07_pending_tasks').find((x:any)=>x.task_id===task.taskId);assert.equal(pending.state,'pending');
 for(const [at,days,expired]of [['2026-11-13T00:00:00+01:00',7,false],['2026-11-13T23:59:59+01:00',7,false],['2026-11-14T00:00:00+01:00',6,true],['2026-11-14T23:59:59+01:00',6,true]]as const){
  const evaluation=projectCivilReference(snapshot.reference,at);assert.equal(evaluation.evaluation!.daysBefore,days);
  assert.equal(evaluateDerivedExpected({slot:'balance',amount:'500.00',due:expected.due},snapshot.reference,at,'0.00').expired,expired);
  const actual=await h.obligations.evaluate(await h.auth(),read,f.b.bookingId,f.q.scheduleId,at);assert.equal(actual.find((x:any)=>x.slot==='balance').expired,expired);
  assert.equal(evaluateTaskDeadline(pending.material.deadline,{date:at.slice(0,10)}).overdue,expired);
 }
 assert.ok(rows(projection,'b04_contributions').every((x:any)=>x.certainty==='estimated'));assert.equal(await businessSnapshot(f.b.bookingId),before);
});
test('H5-011 INTERNAL C01 all applicable canonical calendar categories coexist in one Booking without mutation',async()=>{
 const hold=await holdFixture(h,'2026-11-19T10:15:00Z');await hold.apply(await hold.grant());const command:any=await hold.prepareConversion(),service=command.detail.services[0];service.nights.push({id:uid(),date:'2026-10-20',contributionIds:service.contributions.map((x:any)=>x.id)});command.evidenceId=await hold.f.proof(`booking:detail:${command.acceptanceId}:${await hash(command.detail)}`,command.coverage,new Date().toISOString());await h.booking.apply(await h.auth(),write,command);
 await publishSchedule(command,'2026-10-12T10:00:00Z');const task=await makeTask(command.bookingId,{kind:'unknown',reason:'SYNTHETIC documentary deadline not accredited'},command.bookingId,'document');
 const fallback=await invoiceFixture(h),shared={...fallback,bookingId:command.bookingId,b:{...fallback.b,q:command,detail:command.detail}},need=await requirementFixture(h,shared);await h.requirements.apply(await h.auth(),write,await need.need());
 const before=await businessSnapshot(command.bookingId),calendar:any=await view(command.bookingId,{surface:'calendar'});
 for(const table of ['b04_nights','b04_holds','b05_expected_payments','b07_pending_tasks','b07_requirements'])assert.ok(rows(calendar,table).length,table);
 assert.ok(rows(calendar,'b04_nights').some((x:any)=>x.night_id===service.nights[0].id));assert.ok(rows(calendar,'b04_holds').some((x:any)=>x.hold_id===hold.holdId));assert.ok(rows(calendar,'b07_pending_tasks').some((x:any)=>x.task_id===task.taskId));assert.ok(rows(calendar,'b07_requirements').some((x:any)=>x.requirement_id===need.requirementId));
 const canonicalHold=rows(calendar,'b04_holds').find((x:any)=>x.hold_id===hold.holdId);const resolved=await h.holds.read(await h.auth(),read,canonicalHold.hold_id,canonicalHold.opportunity_id);assert.equal(resolved.parts[0].terms.expiresAt,'2026-11-19T10:15:00Z');assert.ok(calendar.entries.filter((x:any)=>x.source==='crm_private.modification_scope').every((x:any)=>x.certainty==='pending'));
 assert.equal(calendar.mutationAuthority,false);assert.equal(await businessSnapshot(command.bookingId),before);
});
test('H5-011 INTERNAL C05 native multiday20/22/23 anchors and scope-specific configured final count remain independent',async()=>{
 const f=await mixedBooking(),bid=f.command.bookingId,night=f.detail.services[2].nights[0],keys=[['global',bid,'2026-11-20',2],['modality',f.content.modalities[1]!.id,'2026-11-22',4],['service',f.detail.services[0].id,'2026-11-20',2],['night',night.id,'2026-11-23',5]]as const;
 const ids=[];for(const[scope,id,date]of keys){const reference=civilReference({scope,scopeId:id},localDate(date),zone,f.command.versionId,'1');ids.push((await makeTask(bid,{kind:'d020',reference,daysBefore:scope==='modality'?3:7,sourceRef:'SYNTHETIC scope-specific setting',version:'1'},id)).taskId);}
 const before=await businessSnapshot(bid),projection:any=await view(bid),tasks=rows(projection,'b07_pending_tasks');assert.equal(rows(projection,'b04_nights').find((x:any)=>x.night_id===night.id).night_date,'2026-11-23');
 for(const[scope,id,date,days]of keys){const t=tasks.find((x:any)=>x.identity.scopeRef===id);assert.ok(t);assert.equal(t.material.deadline.reference.date,date);assert.equal(t.material.deadline.reference.scope,scope);assert.equal(projectCivilReference(t.material.deadline.reference,'2026-11-18T12:00:00+01:00').evaluation!.daysBefore,days);}
 assert.equal(evaluateTaskDeadline(tasks.find((x:any)=>x.identity.scopeRef===bid).material.deadline,{date:'2026-11-18'}).overdue,true);assert.equal(evaluateTaskDeadline(tasks.find((x:any)=>x.identity.scopeRef===f.content.modalities[1]!.id).material.deadline,{date:'2026-11-18'}).overdue,false);
 assert.ok(rows(projection,'b04_contributions').every((x:any)=>x.certainty==='estimated'));assert.equal(await businessSnapshot(bid),before);
});
test('H5-011 INTERNAL C06 accredited explicit contract25 projects before default20; unreviewed suggestion cannot replace it',async()=>{
 const f=await obligationFixture(h,'1000.00','2026-11-12T10:00:00Z',['2026-11-20','2026-11-22']),recordId=uid();
 await h.evidence.apply(await h.auth(),write,{action:'create',operationId:uid(),targetId:recordId,kind:'document',material:{relation:'original',content_ref:'SYNTHETIC reviewed accepted explicit contractual date 2026-11-25',content_kind:'manual_record',storage_state:'reference_only'},contextKind:'booking',contextId:f.b.bookingId,purpose:'SYNTHETIC express contractual date evidence',sourceRef:'SYNTHETIC accredited manual contract',coverage:f.b.bookingId,reason:'SYNTHETIC reviewed exact agreement'});
 const reference=civilReference({scope:'global',scopeId:f.b.bookingId},localDate('2026-11-25'),zone,recordId,'1','express_contract');await h.obligations.apply(await h.auth(),write,await f.attest({...f.q,definition:{...f.q.definition!,reference}}));
 const suggestion=h.req('evidence',{claim:'SYNTHETIC unverified suggested date 2026-11-29',coverage:f.b.bookingId,certainty:'candidate',source_kind:'manual'},f.b.bookingId,'booking');await h.evidence.apply(await h.auth(),write,{...suggestion,occurredAt:new Date().toISOString()});
 const before=await businessSnapshot(f.b.bookingId),projection:any=await view(f.b.bookingId),snapshot=rows(projection,'b05_schedule_revisions')[0].snapshot;assert.equal(snapshot.reference.date,'2026-11-25');assert.equal(snapshot.reference.basis,'express_contract');assert.equal(snapshot.reference.sourceRef,recordId);assert.equal(projectCivilReference(snapshot.reference,'2026-11-18T12:00:00+01:00').evaluation!.daysBefore,7);assert.ok(projection.entries.some((e:any)=>e.data?.record_id===suggestion.targetId&&e.certainty==='pending'));assert.equal(rows(await view(f.b.bookingId),'b05_schedule_revisions')[0].snapshot.reference.date,'2026-11-25');assert.equal(await businessSnapshot(f.b.bookingId),before);
});
test('H5-011 INTERNAL C07 current projection follows actual authorized hour/date changes and retains prior versions',async()=>{
 const m=await modificationFixture(h),id=m.bookingId,original:any=await view(id,{surface:'calendar'}),first=original.entries.find((x:any)=>x.reference===m.f.service.id);assert.equal(first.scope.date,'2026-10-20');
 await m.run(await m.request([{id:m.partId,scope:m.scope,expectedScopeRevision:1,desired:{schedule:{requested:'11:00',alternatives:['10:00','12:30'],final:'12:30:00+02:00',sourceRef:'SYNTHETIC exact client agreement'}},aspects:['time'],dependencies:[]}]));await m.run(await m.evaluate());await m.run(await m.approve());await m.run(await m.apply());
 const hour:any=(await view(id,{surface:'calendar'}))!.entries.find((x:any)=>x.reference===m.f.service.id);assert.equal(hour.scope.date,'2026-10-20');assert.equal(hour.scope.schedule.final,'12:30:00+02:00');
 const next=await modificationFixture(h,m.f);await next.run(await next.request([{id:next.partId,scope:next.scope,expectedScopeRevision:2,desired:{date:'2026-10-22'},aspects:['date'],dependencies:[]}]));await next.run(await next.evaluate());await next.run(await next.approve());await next.run(await next.apply());
 const changed:any=(await view(id,{surface:'calendar'}))!.entries.find((x:any)=>x.reference===m.f.service.id);assert.equal(changed.scope.date,'2026-10-22');const ref=(date:string)=>civilReference({scope:'service',scopeId:m.f.service.id},localDate(date),zone,m.modificationId,'1');assert.equal(projectCivilReference(ref(first.scope.date),'2026-10-13T23:59:59+02:00').evaluation!.daysBefore,7);assert.equal(projectCivilReference(ref(hour.scope.date),'2026-10-13T23:59:59+02:00').evaluation!.daysBefore,7);assert.equal(projectCivilReference(ref(changed.scope.date),'2026-10-13T23:59:59+02:00').evaluation!.daysBefore,9);
 const history:any=await view(id);assert.equal(rows(history,'b04_operational_versions').filter((x:any)=>x.scope_id===m.f.service.id).length,2);assert.ok(rows(history,'b06_modifications').some((x:any)=>x.modification_id===m.modificationId));
});
test('H5-011 INTERNAL C08 unknown deadlines and absent zone stay pending while independent Booking continues',async()=>{
 const a=await bookingFixture(h),b=await bookingFixture(h);await h.booking.apply(await h.auth(),write,a.q);await h.booking.apply(await h.auth(),write,b.q);const task=await makeTask(a.q.bookingId,{kind:'unknown',reason:'SYNTHETIC legitimate source/reference zone not known'});
 const pending:any=await view(a.q.bookingId,{surface:'calendar'}),known:any=await view(b.q.bookingId,{surface:'calendar'}),t=rows(pending,'b07_pending_tasks').find((x:any)=>x.task_id===task.taskId);assert.deepEqual(evaluateTaskDeadline(t.material.deadline,{}),{known:false,overdue:false});assert.equal(projectCivilReference(null,'2026-11-18T12:00:00+01:00').certainty,'pending');assert.ok(known.entries.length);assert.ok(known.entries.every((x:any)=>x.bookingId===undefined||x.bookingId===b.q.bookingId));await assert.rejects(view(a.q.bookingId,{serverZone:'Europe/Madrid',leadDays:7}),/PROJECTION_INPUT_INVALID/);assert.equal(t.state,'pending');
});
test('H5-011 INTERNAL C02 real pagination reconstructs same scoped facts without duplication or scope extension',async()=>{
 const f=await bookingFixture(h);await h.booking.apply(await h.auth(),write,f.q);const all:any=await view(f.q.bookingId),collected:any[]=[];let after:string|undefined;
 do{const page:any=await view(f.q.bookingId,{pageSize:3,...(after?{after}:{})});collected.push(...page.entries);after=page.nextPage;}while(after);
 assert.deepEqual(collected,all.entries);assert.equal(new Set(collected.map(x=>x.reference)).size,collected.length);const first:any=await view(f.q.bookingId,{pageSize:3});await assert.rejects(view(f.q.bookingId,{pageSize:3,destination:'customer',after:first.nextPage}));
